function normalize(s) { return String(s || '').toLowerCase().replace(/\s+/g, ' ').trim(); }
const body = $('Webhook').first().json.body || {};
const expected = String(body.expected_name || '').trim();
const docType = String(body.document_type || '');

let text = '';
try {
  const r = ($json.responses && $json.responses[0]) || {};
  text = (r.fullTextAnnotation && r.fullTextAnnotation.text) || (r.textAnnotations && r.textAnnotations[0] && r.textAnnotations[0].description) || '';
} catch (e) {
  text = '';
}

let status, note;
if (!text || !text.trim()) {
  status = 'missing';
  note = 'No readable text could be extracted from the document, or the file at blob_url could not be reached.';
} else {
  const normText = normalize(text);
  const normExpected = normalize(expected);
  if (normExpected && !normText.includes(normExpected)) {
    status = 'name_mismatch';
    note = 'The expected name "' + expected + '" was not found in the extracted document text.';
  } else {
    status = 'present';
    note = 'The document is present and the expected name was found in the text. (Expiry-date checking was intentionally removed: free-text OCR cannot reliably tell an issue date from an expiry date, so this is a completeness/format check only, not an authenticity or validity claim.)';
  }
}
return { json: { document_type: docType, status, note } };
